48	/// Distinguishes why sandbox is unavailable so error messages are accurate.
49	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
50	pub enum SandboxReadiness {
51	    /// Docker is available and sandbox is enabled.
52	    Available,
53	    /// User explicitly disabled sandboxing (SANDBOX_ENABLED=false).
54	    DisabledByConfig,
55	    /// Sandbox is enabled but Docker is not running or not installed.
56	    DockerUnavailable,
57	}
