888	    fn check_cooldown(&self, routine: &Routine) -> bool {
889	        if let Some(last_run) = routine.last_run_at {
890	            let elapsed = Utc::now().signed_duration_since(last_run);
891	            let cooldown = chrono::Duration::from_std(routine.guardrails.cooldown)
892	                .unwrap_or(chrono::Duration::seconds(300));
893	            if elapsed < cooldown {
894	                return false;
895	            }
896	        }
897	        true
898	    }
