24	/// State of a job.
25	#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
26	#[serde(rename_all = "snake_case")]
27	pub enum JobState {
28	    /// Job is waiting to be started.
29	    Pending,
30	    /// Job is currently being worked on.
31	    InProgress,
32	    /// Job work is complete, awaiting submission.
33	    Completed,
34	    /// Job has been submitted for review.
35	    Submitted,
36	    /// Job was accepted/paid.
37	    Accepted,
38	    /// Job failed and cannot be completed.
39	    Failed,
40	    /// Job is stuck and needs repair.
41	    Stuck,
42	    /// Job was cancelled.
43	    Cancelled,
44	}
