46	impl JobState {
47	    /// Check if this state allows transitioning to another state.
48	    pub fn can_transition_to(&self, target: JobState) -> bool {
49	        use JobState::*;
50	
51	        // Allow idempotent Completed -> Completed transition.
52	        // Both the execution loop and the worker wrapper may race to mark a
53	        // job complete; the second call should be a harmless no-op rather
54	        // than an error that masks the successful completion.
55	        if matches!((self, target), (Completed, Completed)) {
56	            return true;
57	        }
58	
59	        matches!(
60	            (self, target),
61	            // From Pending
62	            (Pending, InProgress) | (Pending, Cancelled) |
63	            // From InProgress
64	            (InProgress, Completed) | (InProgress, Failed) |
65	            (InProgress, Stuck) | (InProgress, Cancelled) |
66	            // From Completed
67	            (Completed, Submitted) | (Completed, Failed) |
68	            // From Submitted
69	            (Submitted, Accepted) | (Submitted, Failed) |
70	            // From Stuck (can recover or fail)
71	            (Stuck, InProgress) | (Stuck, Failed) | (Stuck, Cancelled)
72	        )
73	    }
74	
75	    /// Check if this is a terminal state.
76	    pub fn is_terminal(&self) -> bool {
77	        matches!(self, Self::Accepted | Self::Failed | Self::Cancelled)
78	    }
79	
80	    /// Check if the job is active (not terminal).
81	    pub fn is_active(&self) -> bool {
82	        !self.is_terminal()
83	    }
84	
85	    /// Check if this job consumes a parallel execution slot.
86	    ///
87	    /// Only jobs in Pending, InProgress, or Stuck states consume execution resources
88	    /// and should count toward the parallel job limit. Completed and Submitted jobs
89	    /// are in the state machine but are no longer actively executing.
90	    pub fn is_parallel_blocking(&self) -> bool {
91	        matches!(self, Self::Pending | Self::InProgress | Self::Stuck)
92	    }
93	}
