255	    /// Transition to a new state.
256	    pub fn transition_to(
257	        &mut self,
258	        new_state: JobState,
259	        reason: Option<String>,
260	    ) -> Result<(), String> {
261	        if !self.state.can_transition_to(new_state) {
262	            return Err(format!(
263	                "Cannot transition from {} to {}",
264	                self.state, new_state
265	            ));
266	        }
267	
268	        // Idempotent: already in the target state, skip recording a duplicate
269	        // transition. This handles the Completed -> Completed race between
270	        // execution_loop and the worker wrapper.
271	        if self.state == new_state {
272	            tracing::debug!(
273	                job_id = %self.job_id,
274	                state = %self.state,
275	                "idempotent state transition (already in target state), skipping"
276	            );
277	            return Ok(());
278	        }
279	
280	        let transition = StateTransition {
281	            from: self.state,
282	            to: new_state,
283	            timestamp: Utc::now(),
284	            reason,
285	        };
286	
287	        self.transitions.push(transition);
288	
289	        // Cap transition history to prevent unbounded memory growth
290	        const MAX_TRANSITIONS: usize = 200;
291	        if self.transitions.len() > MAX_TRANSITIONS {
292	            let drain_count = self.transitions.len() - MAX_TRANSITIONS;
293	            self.transitions.drain(..drain_count);
294	        }
295	
296	        self.state = new_state;
297	
298	        // Update timestamps
299	        match new_state {
300	            JobState::InProgress if self.started_at.is_none() => {
301	                self.started_at = Some(Utc::now());
302	            }
303	            JobState::Completed | JobState::Accepted | JobState::Failed | JobState::Cancelled => {
304	                self.completed_at = Some(Utc::now());
305	            }
306	            _ => {}
307	        }
308	
309	        Ok(())
310	    }
311	
312	    /// Add to the actual cost.
313	    pub fn add_cost(&mut self, cost: Decimal) {
314	        self.actual_cost += cost;
315	    }
