317	    /// Record token usage from an LLM call. Returns an error if the token
318	    /// budget has been exceeded after this addition.
319	    pub fn add_tokens(&mut self, tokens: u64) -> Result<(), TokenBudgetExceeded> {
320	        self.total_tokens_used += tokens;
321	        if self.max_tokens > 0 && self.total_tokens_used > self.max_tokens {
322	            Err(TokenBudgetExceeded {
323	                used: self.total_tokens_used,
324	                limit: self.max_tokens,
325	            })
326	        } else {
327	            Ok(())
328	        }
329	    }
330	
331	    /// Check whether the monetary budget has been exceeded.
332	    pub fn budget_exceeded(&self) -> bool {
333	        if let Some(ref budget) = self.budget {
334	            self.actual_cost > *budget
335	        } else {
336	            false
337	        }
338	    }
339	
340	    /// Get the duration since the job started.
341	    pub fn elapsed(&self) -> Option<Duration> {
342	        self.started_at.map(|start| {
343	            let end = self.completed_at.unwrap_or_else(Utc::now);
344	            let duration = end.signed_duration_since(start);
345	            Duration::from_secs(duration.num_seconds().max(0) as u64)
346	        })
347	    }
