349	    /// Mark the job as stuck.
350	    pub fn mark_stuck(&mut self, reason: impl Into<String>) -> Result<(), String> {
351	        self.transition_to(JobState::Stuck, Some(reason.into()))
352	    }
353	
354	    /// Attempt to recover from stuck state.
355	    pub fn attempt_recovery(&mut self) -> Result<(), String> {
356	        if self.state != JobState::Stuck {
357	            return Err("Job is not stuck".to_string());
358	        }
359	        self.repair_attempts += 1;
360	        self.transition_to(JobState::InProgress, Some("Recovery attempt".to_string()))
361	    }
362	}
