385	        // and the worker wrapper call mark_completed(). The second call
386	        // must succeed without error and must not record a duplicate
387	        // transition.
388	        let mut ctx = JobContext::new("Test", "Idempotent completion test");
389	        ctx.transition_to(JobState::InProgress, None).unwrap();
390	        ctx.transition_to(JobState::Completed, Some("first".into()))
