112	#[async_trait]
113	impl SelfRepair for DefaultSelfRepair {
114	    async fn detect_stuck_jobs(&self) -> Vec<StuckJob> {
115	        let stuck_ids = self
116	            .context_manager
117	            .find_stuck_jobs_with_threshold(Some(self.stuck_threshold))
118	            .await;
119	        let mut stuck_jobs = Vec::new();
120	
121	        for job_id in stuck_ids {
122	            if let Ok(ctx) = self.context_manager.get_context(job_id).await
123	                && matches!(ctx.state, JobState::Stuck | JobState::InProgress)
124	            {
125	                // InProgress jobs detected by threshold need to be transitioned
126	                // to Stuck before they can be repaired (attempt_recovery requires
127	                // Stuck state). These jobs already passed the threshold check in
128	                // find_stuck_jobs_with_threshold, so skip the duration filter below.
129	                let just_transitioned = ctx.state == JobState::InProgress;
130	                if just_transitioned {
131	                    let reason = "exceeded stuck_threshold";
132	                    let transition = self
133	                        .context_manager
134	                        .update_context(job_id, |ctx| ctx.mark_stuck(reason))
135	                        .await;
136	                    match transition {
137	                        Ok(Ok(())) => {}
138	                        Ok(Err(e)) => {
139	                            tracing::warn!(
140	                                job = %job_id,
141	                                "Failed to mark InProgress job as Stuck: {}",
142	                                e
143	                            );
144	                            continue;
145	                        }
146	                        Err(e) => {
147	                            tracing::warn!(
148	                                job = %job_id,
149	                                "Failed to transition InProgress job to Stuck: {}",
150	                                e
151	                            );
152	                            continue;
153	                        }
154	                    }
155	                }
156	
157	                // Re-fetch context after potential InProgress->Stuck transition
158	                // so that stuck_since picks up the new transition timestamp.
159	                let ctx = match self.context_manager.get_context(job_id).await {
160	                    Ok(c) => c,
161	                    Err(_) => continue,
162	                };
163	
164	                // Use the timestamp of the most recent Stuck transition, not started_at.
165	                // A job that ran for hours before becoming stuck should not immediately
166	                // exceed the threshold — we measure from when it actually became stuck.
167	                let stuck_since = ctx
168	                    .transitions
169	                    .iter()
170	                    .rev()
171	                    .find(|t| t.to == JobState::Stuck)
172	                    .map(|t| t.timestamp);
173	
174	                let stuck_duration = stuck_since
175	                    .map(|ts| {
176	                        let duration = Utc::now().signed_duration_since(ts);
