201	    async fn repair_stuck_job(&self, job: &StuckJob) -> Result<RepairResult, RepairError> {
202	        // Check if we've exceeded max repair attempts
203	        if job.repair_attempts >= self.max_repair_attempts {
204	            return Ok(RepairResult::ManualRequired {
205	                message: format!(
206	                    "Job {} has exceeded maximum repair attempts ({})",
207	                    job.job_id, self.max_repair_attempts
208	                ),
209	            });
210	        }
211	
212	        // Try to recover the job.
213	        // If the job is still InProgress (detected via stuck_threshold), transition
214	        // it to Stuck first so that attempt_recovery() can move it back to InProgress.
215	        let result = self
216	            .context_manager
217	            .update_context(job.job_id, |ctx| {
218	                if ctx.state == JobState::InProgress {
219	                    ctx.transition_to(JobState::Stuck, Some("exceeded stuck_threshold".into()))?;
220	                }
221	                ctx.attempt_recovery()
222	            })
223	            .await;
224	
225	        match result {
226	            Ok(Ok(())) => {
227	                tracing::info!("Successfully recovered job {}", job.job_id);
228	                Ok(RepairResult::Success {
229	                    message: format!("Job {} recovered and will be retried", job.job_id),
230	                })
231	            }
232	            Ok(Err(e)) => {
233	                tracing::warn!("Failed to recover job {}: {}", job.job_id, e);
234	                Ok(RepairResult::Retry {
235	                    message: format!("Recovery attempt failed: {}", e),
236	                })
237	            }
238	            Err(e) => Err(RepairError::Failed {
239	                target_type: "job".to_string(),
240	                target_id: job.job_id,
241	                reason: e.to_string(),
242	            }),
243	        }
244	    }
