247	        let Some(ref store) = self.store else {
248	            return vec![];
249	        };
250	
251	        // Threshold: 5 failures before considering a tool broken
252	        match store.get_broken_tools(5).await {
253	            Ok(tools) => {
254	                if !tools.is_empty() {
255	                    tracing::info!("Detected {} broken tools needing repair", tools.len());
256	                }
257	                tools
258	            }
259	            Err(e) => {
260	                tracing::warn!("Failed to detect broken tools: {}", e);
261	                vec![]
262	            }
263	        }
264	    }
