266	    async fn repair_broken_tool(&self, tool: &BrokenTool) -> Result<RepairResult, RepairError> {
267	        let Some(ref builder) = self.builder else {
268	            return Ok(RepairResult::ManualRequired {
269	                message: format!("Builder not available for repairing tool '{}'", tool.name),
270	            });
271	        };
272	
273	        let Some(ref store) = self.store else {
274	            return Ok(RepairResult::ManualRequired {
275	                message: "Store not available for tracking repair".to_string(),
276	            });
277	        };
278	
279	        // Check repair attempt limit
280	        if tool.repair_attempts >= self.max_repair_attempts {
281	            return Ok(RepairResult::ManualRequired {
282	                message: format!(
283	                    "Tool '{}' exceeded max repair attempts ({})",
284	                    tool.name, self.max_repair_attempts
285	                ),
286	            });
287	        }
288	
289	        tracing::info!(
290	            "Attempting to repair tool '{}' (attempt {})",
291	            tool.name,
292	            tool.repair_attempts + 1
293	        );
294	
295	        // Increment repair attempts
296	        if let Err(e) = store.increment_repair_attempts(&tool.name).await {
297	            tracing::warn!("Failed to increment repair attempts: {}", e);
298	        }
299	
300	        // Create BuildRequirement for repair
301	        let requirement = BuildRequirement {
302	            name: tool.name.clone(),
303	            description: format!(
304	                "Repair broken WASM tool.\n\n\
305	                 Tool name: {}\n\
306	                 Previous error: {}\n\
307	                 Failure count: {}\n\n\
308	                 Analyze the error, fix the implementation, and rebuild.",
309	                tool.name,
310	                tool.last_error.as_deref().unwrap_or("Unknown error"),
311	                tool.failure_count
312	            ),
313	            software_type: SoftwareType::WasmTool,
314	            language: Language::Rust,
315	            input_spec: None,
316	            output_spec: None,
317	            dependencies: vec![],
318	            capabilities: vec!["http".to_string(), "workspace".to_string()],
319	        };
320	
321	        // Attempt to build/repair
322	        match builder.build(&requirement).await {
323	            Ok(result) if result.success => {
324	                tracing::info!(
325	                    "Successfully rebuilt tool '{}' after {} iterations",
326	                    tool.name,
327	                    result.iterations
328	                );
329	
330	                // Mark as repaired in database
331	                if let Err(e) = store.mark_tool_repaired(&tool.name).await {
332	                    tracing::warn!("Failed to mark tool as repaired: {}", e);
333	                }
334	
335	                if result.registered {
336	                    tracing::info!("Repaired tool '{}' auto-registered by builder", tool.name);
337	                }
338	
339	                Ok(RepairResult::Success {
340	                    message: format!(
341	                        "Tool '{}' repaired successfully after {} iterations",
342	                        tool.name, result.iterations
343	                    ),
344	                })
345	            }
346	            Ok(result) => {
347	                // Build completed but failed
348	                tracing::warn!(
349	                    "Repair build for '{}' completed but failed: {:?}",
350	                    tool.name,
351	                    result.error
352	                );
353	                Ok(RepairResult::Retry {
354	                    message: format!(
355	                        "Repair attempt {} for '{}' failed: {}",
356	                        tool.repair_attempts + 1,
357	                        tool.name,
358	                        result.error.unwrap_or_else(|| "Unknown error".to_string())
359	                    ),
360	                })
361	            }
362	            Err(e) => {
363	                tracing::error!("Repair build for '{}' errored: {}", tool.name, e);
364	                Ok(RepairResult::Retry {
365	                    message: format!("Repair build error: {}", e),
366	                })
367	            }
368	        }
369	    }
370	}
