35	/// Resolve a job ID from a full UUID or a short prefix (like git short SHAs).
36	///
37	/// Tries full UUID parse first. If that fails, treats the input as a hex prefix
38	/// and searches the context manager for a unique match.
39	async fn resolve_job_id(input: &str, context_manager: &ContextManager) -> Result<Uuid, ToolError> {
40	    // Fast path: full UUID
41	    if let Ok(id) = Uuid::parse_str(input) {
42	        return Ok(id);
43	    }
44	
45	    // Require a minimum prefix length to limit brute-force enumeration.
46	    if input.len() < 4 {
47	        return Err(ToolError::InvalidParameters(
48	            "job ID prefix must be at least 4 hex characters".to_string(),
49	        ));
50	    }
51	
52	    // Prefix match against known jobs
53	    let input_lower = input.to_lowercase();
54	    let all_ids = context_manager.all_jobs().await;
55	    let matches: Vec<Uuid> = all_ids
56	        .into_iter()
57	        .filter(|id| {
58	            let hex = id.to_string().replace('-', "");
59	            hex.starts_with(&input_lower)
60	        })
61	        .collect();
62	
63	    match matches.len() {
64	        1 => Ok(matches[0]),
65	        0 => Err(ToolError::InvalidParameters(format!(
66	            "no job found matching prefix '{}'",
67	            input
68	        ))),
69	        n => Err(ToolError::InvalidParameters(format!(
70	            "ambiguous prefix '{}' matches {} jobs, provide more characters",
71	            input, n
72	        ))),
73	    }
74	}
