177	    /// Parse and validate the `credentials` parameter.
178	    ///
179	    /// Each key is a secret name (must exist in SecretsStore), each value is the
180	    /// env var name the container should receive it as. Returns an empty vec if
181	    /// no credentials were requested.
182	    async fn parse_credentials(
183	        &self,
184	        params: &serde_json::Value,
185	        user_id: &str,
186	    ) -> Result<Vec<CredentialGrant>, ToolError> {
187	        let creds_obj = match params.get("credentials").and_then(|v| v.as_object()) {
188	            Some(obj) if !obj.is_empty() => obj,
189	            _ => return Ok(vec![]),
190	        };
191	
192	        const MAX_CREDENTIAL_GRANTS: usize = 20;
193	        if creds_obj.len() > MAX_CREDENTIAL_GRANTS {
194	            return Err(ToolError::InvalidParameters(format!(
195	                "too many credential grants ({}, max {})",
196	                creds_obj.len(),
197	                MAX_CREDENTIAL_GRANTS
198	            )));
199	        }
200	
201	        let secrets = match &self.secrets_store {
202	            Some(s) => s,
203	            None => {
204	                return Err(ToolError::ExecutionFailed(
205	                    "credentials requested but no secrets store is configured. \
206	                     Set SECRETS_MASTER_KEY to enable credential management."
207	                        .to_string(),
208	                ));
209	            }
210	        };
211	
212	        let mut grants = Vec::with_capacity(creds_obj.len());
213	        for (secret_name, env_var_value) in creds_obj {
214	            let env_var = env_var_value.as_str().ok_or_else(|| {
215	                ToolError::InvalidParameters(format!(
216	                    "credential env var for '{}' must be a string",
217	                    secret_name
218	                ))
219	            })?;
220	
221	            validate_env_var_name(env_var)?;
222	
223	            // Validate the secret actually exists
224	            let exists = secrets.exists(user_id, secret_name).await.map_err(|e| {
225	                ToolError::ExecutionFailed(format!(
226	                    "failed to check secret '{}': {}",
227	                    secret_name, e
228	                ))
229	            })?;
230	
231	            if !exists {
232	                return Err(ToolError::ExecutionFailed(format!(
233	                    "secret '{}' not found. Store it first via 'ironclaw tool auth' or the web UI.",
234	                    secret_name
235	                )));
236	            }
237	
238	            grants.push(CredentialGrant {
239	                secret_name: secret_name.clone(),
240	                env_var: env_var.to_string(),
241	            });
242	        }
243	
244	        Ok(grants)
245	    }
