1872	/// Sanitize a summary string from job transitions before using in notifications.
1873	///
1874	/// `last_reason` comes from untrusted container code, so we:
1875	/// 1. Strip control characters (except newline) to prevent terminal injection
1876	/// 2. Strip HTML tags to prevent injection in web-rendered notifications
1877	/// 3. Collapse multiple whitespace/newlines to single spaces for cleaner output
1878	/// 4. Truncate to 500 chars to prevent oversized notifications
1879	#[cfg(test)]
1880	fn sanitize_summary(s: &str) -> String {
1881	    // Strip control characters (keep newline for now, collapse later)
1882	    let no_control: String = s
1883	        .chars()
1884	        .filter(|c| !c.is_control() || *c == '\n')
1885	        .collect();
1886	
1887	    // Strip HTML tags (e.g. <script>, <img>, <a href=...>)
1888	    let no_html = strip_html_tags(&no_control);
1889	
1890	    // Collapse whitespace: multiple spaces/newlines become a single space
1891	    let collapsed: String = no_html.split_whitespace().collect::<Vec<_>>().join(" ");
1892	
1893	    // Truncate to reasonable length
1894	    if collapsed.len() <= 500 {
1895	        collapsed
1896	    } else {
1897	        // Find a safe char boundary for truncation
1898	        let mut end = 500;
1899	        while !collapsed.is_char_boundary(end) && end > 0 {
1900	            end -= 1;
1901	        }
1902	        format!("{}...", &collapsed[..end])
1903	    }
1904	}
